function isDevelopment() {
  return process.env.ELEVENTY_ENV === "development";
}

module.exports = {
  eleventyComputed: {
    permalink: (data) => {
      if (!isDevelopment() && !data.published) return false;
      return `/${data.category}/${data.page.fileSlug}/`;
    },
    eleventyExcludeFromCollections: (data) => !isDevelopment() && !data.published,
    // Stable originals are copied to /img for social cards and structured data.
    // Page images still use the optimized variants generated by Eleventy Image.
    coverUrl: (data) => data.cover || null,
    ogImage: (data) => data.cover || null,
  }
};
